#!/bin/bash
# melee rework of the 3 normal teachers + the 8 new FPE Green characters (sequential)
cd "$(dirname "$0")/.." || exit 1
R="Trust only the confirmed art. Research canon+fan attacks, end with 10-12+ fully animated abilities."
M="MELEE FOCUS (user rule): this character is almost never seen using ranged attacks in canon/fan works, so REMOVE projectile/long-range attacks (boomerangs, thrown objects, rains of projectiles, beams, bullets) and replace them with close-range melee attacks (gap-closing dashes/leaps count as melee; area slams, spins, combos, grabs, bleed/status on hit are fine). Keep the model; edit the abilities + the animations in tools/bbgen/chars/<name>.py and regenerate. Remove the animations of deleted abilities. Height must stay unchanged (check the max cube top y in the .bbmodel before/after)."
tools/run_agent.sh miss_circle MissCircle "$M The bbmodel was scaled by hand to 2.92 blocks (max y 46.7): if you regenerate with the script, multiply all sizes by 1.1145 or the model shrinks. $R"
tools/run_agent.sh miss_thavel MissThavel "$M (ABC-block teacher: blocks/letters become melee bashes, claws, stabs). $R"
tools/run_agent.sh miss_bloomie MissBloomie "$M (cleaver/blade teacher: wave/bomb attacks become melee blade combos). $R"
tools/run_agent.sh green_alice GreenAlice "NEW character, placeholder currently = copy of Alice. Spec names: 'green_alice' (phase 1) and 'green_alice_boss' (phase 2), class GreenAlice (copy of Alice.java as starting point; same transform/boss plumbing, faction GREEN_TEACHER, edit hitbox lines in ModEntities if needed). Art: docs/ref/confirmed/green_alice_phase1.png (brown messy hair with ahoge, glowing green eyes, white lab-coat jacket over black trousers, triangle pendant; the green tint in the frame is just lighting - give her a toxic-green accent) and green_alice_phase2.png (GIANT black spider-like form: huge black silhouette body with ~8 long jointed spider legs, tiny head with ahoge, red-black glow). Phase 2: giant, whole body pitch black, rough flashy attacks (leg stabs, web/tentacle grabs, black eruptions from the ground). Distinct from Alice/Danger Alice. $R"
tools/run_agent.sh green_thavel GreenThavel "NEW character (placeholder class currently, model is a Fen copy - replace everything). Art docs/ref/confirmed/green_thavel.jpg: dark hair with white antler-like horns/ears and green goggles on the head, white lab coat with ID badge, black skirt, BIG green gloves holding clipboards, tall green boots, small triangle badge, grin. Faction GREEN_TEACHER. $M $R"
tools/run_agent.sh green_bloomie GreenBloomie "NEW character (placeholder class, model is a Fen copy - replace everything). Art docs/ref/confirmed/green_bloomie.jpg: spiky black hair, grey gas mask with goggles, white lab coat with ID badge, black tights, green boots, a GIANT syringe with green liquid as weapon, a grey briefcase with a triangle emblem. Faction GREEN_TEACHER. Syringe/poison themed; ranged allowed only sparingly (science teacher). $R"
tools/run_agent.sh mutant_claire MutantClaire "NEW mutant student (FPE Green). Art docs/ref/confirmed/mutant_claire.png (sheet: mutants_sheet.png, label CLAIRE 001): white shaggy hood/wolf-like head with a huge jagged-tooth mouth and a black eye, oversized white jacket and shorts, hunched, black clawed feet. Placeholder model is a Fen copy - replace everything. Faction MUTANT. $R"
tools/run_agent.sh mutant_engel MutantEngel "NEW mutant student (FPE Green). Art docs/ref/confirmed/mutant_engel.png (label ENGEL 002): TALL, spiky white hair with a feather, one big ink-black clawed arm and black legs, white shirt/shorts with red-green stripes on arm and legs, wide cracked grin. Placeholder model is a Fen copy - replace everything. Faction MUTANT. $R"
tools/run_agent.sh mutant_bubble MutantBubble "NEW mutant student (FPE Green). Art docs/ref/confirmed/mutant_bubble.png (label BUBBLE 003): SMALL, fluffy foam-cloud hair and lower body, floating soap bubbles, white jumpsuit with black harness straps/buckles, mismatched eyes (one pink swirl), tiny duck/rubber toy on head. Placeholder model is a Fen copy - replace everything. Hitbox is small (0.6x1.2). Faction MUTANT. Foam/bubble themed attacks. $R"
tools/run_agent.sh mutant_lana MutantLana "NEW mutant student (FPE Green). Art docs/ref/confirmed/mutant_lana.png (label LANA 004): long grey hair with an ahoge, huge round black eyes and a wide grin, white shirt and shorts, white boots, carries a big-toothed black monster-bag/mask creature. Placeholder model is a Fen copy - replace everything. Faction MUTANT. $R"
tools/run_agent.sh mutant_abbie MutantAbbie "NEW mutant student (FPE Green). Art docs/ref/confirmed/mutant_abbie.png (label ABBIE 005): all-black silhouette, spiky hair with a small leaf sprout on top, hunched and hugging herself, jagged tail and claws, faint pink mouth. Placeholder model is a Fen copy - replace everything. Faction MUTANT. $R"
echo QUEUE_DONE
